// Generuje ustrukturyzowany brief eskalacyjny i przygotowuje payload dla Slacka.
const input = $input.first().json;
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const dateStamp = `${now.getFullYear()}_${pad(now.getMonth()+1)}_${pad(now.getDate())}`;
const timeStamp = `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const escalationId = `esc_${dateStamp}_${timeStamp}_${Math.floor(Math.random()*10000).toString().padStart(4,'0')}`;

const priority = ['Low','Medium','High'].includes(input.priority) ? input.priority : 'Medium';
const priorityEmoji = { High: ':rotating_light:', Medium: ':warning:', Low: ':information_source:' };
const priorityColor = { High: '#BF4859', Medium: '#B27916', Low: '#5A6478' };

const brief = {
  escalation_id: escalationId,
  priority,
  reason_code: input.reason_code || 'unknown',
  session_id: input.session_id,
  customer: input.customer || {},
  order: input.order || {},
  shipment: input.shipment || {},
  summary: input.summary || '',
  created_at: now.toISOString()
};

// Payload Slack Block Kit
const slackPayload = {
  attachments: [{
    color: priorityColor[priority],
    blocks: [
      {
        type: 'header',
        text: { type: 'plain_text', text: `${priorityEmoji[priority]} Eskalacja ${priority}: ${input.reason_code}` }
      },
      {
        type: 'section',
        fields: [
          { type: 'mrkdwn', text: `*Klient:*\n${input.customer?.name || 'nieznany'}\n${input.customer?.email || ''}` },
          { type: 'mrkdwn', text: `*Zamowienie:*\n#${input.order?.id || '-'}\n${input.order?.value_pln || 0} PLN` },
          { type: 'mrkdwn', text: `*Kanal:*\n${input.customer?.channel || 'widget'}` },
          { type: 'mrkdwn', text: `*Kurier:*\n${input.shipment?.carrier || '-'}\n${input.shipment?.tracking || '-'}` }
        ]
      },
      {
        type: 'section',
        text: { type: 'mrkdwn', text: `*Kontekst:*\n${input.summary || 'brak podsumowania'}` }
      },
      {
        type: 'actions',
        elements: [
          { type: 'button', text: { type: 'plain_text', text: 'Przejmuje' }, style: 'primary', value: `take:${escalationId}` },
          { type: 'button', text: { type: 'plain_text', text: 'Zamknij bez akcji' }, value: `close:${escalationId}` },
          { type: 'button', text: { type: 'plain_text', text: 'Odsylam do agenta' }, value: `return:${escalationId}` }
        ]
      },
      {
        type: 'context',
        elements: [
          { type: 'mrkdwn', text: `escalation_id: \`${escalationId}\` · session: \`${input.session_id}\`` }
        ]
      }
    ]
  }]
};

return [{ json: { brief, slackPayload, escalationId } }];
